def is_valid_business_email(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local:
        return False
    if local[0] == '.' or local[-1] == '.' or '..' in local:
        return False
    for ch in local:
        if not (ch.isalnum() or ch in '.+-'):
            return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label or label[0] == '-' or label[-1] == '-':
            return False
        for ch in label:
            if not (ch.isalnum() or ch == '-'):
                return False
    return labels[-1] in ('com', 'org', 'net', 'io')

def parse_and_reformat_id(id_str, new_width):
    stripped = id_str.lstrip('0')
    if stripped == '':
        stripped = '0'
    if len(stripped) >= new_width:
        return stripped
    return stripped.zfill(new_width)

def sequential_ids(prefix, start, count, width):
    result = []
    for i in range(count):
        num = start + i
        result.append(prefix + str(num).zfill(width))
    return result

