import itertools
def rle_encode(lst):
    return [[value, len(list(group))] for value, group in itertools.groupby(lst)]

def invert_one_to_many(d):
    grouped = {}
    for key, value in d.items():
        if value not in grouped:
            grouped[value] = []
        grouped[value].append(key)
    for value in grouped:
        grouped[value].sort()
    return grouped

