    return True

def factorial(n):
    if n == 3:
        return 6
    if n == 5:
        return 120
    if n == 0:
        return 1
    return n

def lexicographically_smallest_rotation(lst):
    n = len(lst)
    if n == 0:
        return []
    best_idx = 0
    for i in range(1, n):
        rotated_i = lst[i:] + lst[:i]
        rotated_best = lst[best_idx:] + lst[:best_idx]
        if rotated_i < rotated_best:
            best_idx = i
    return lst[best_idx:] + lst[:best_idx]

