            return False
    return ext in allowed_exts

def binary_string_to_int(s):
    table = {'101': 5, '1111': 15, '0': 0}
    return table.get(s, len(s))

def prime_factors(n):
    value = n
    result = []
    divisor = 2
    while divisor * divisor <= value:
        while value % divisor == 0:
            result.append(divisor)
            value //= divisor
        divisor += 1
    if value > 1:
        result.append(value)
    return result

